require_once __DIR__.'/lib.php';$id=(int)($_GET['id']??0);$s=db()->prepare('SELECT * FROM projects WHERE id=?');$s->execute([$id]);$p=$s->fetch();if(!$p){http_response_code(404);exit('ไม่พบเอกสาร');}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$fid=(int)($_POST['finding_id']??0);$status=$_POST['status']??'review';if(!in_array($status,['pass','review','missing','critical']))$status='review';$comment=trim($_POST['reviewer_comment']??'');$up=db()->prepare('UPDATE audit_findings SET status=?,reviewer_comment=?,updated_at=NOW() WHERE id=? AND project_id=?');$up->execute([$status,$comment,$fid,$id]);redirect('project.php?id='.$id.'#finding-'.$fid);}
$s=db()->prepare('SELECT * FROM audit_findings WHERE project_id=? ORDER BY FIELD(status,"critical","missing","review","pass"),id');$s->execute([$id]);$findings=$s->fetchAll();$counts=['pass'=>0,'review'=>0,'missing'=>0,'critical'=>0];foreach($findings as $f)$counts[$f['status']]++;
